<?php
namespace App\Http\Controllers;
use App\Http\Requests\BudgetRequest; use App\Models\Budget; use App\Services\BudgetTracker;
class BudgetController extends Controller { public function index(BudgetTracker $tracker){$budgets=Budget::with('expenses')->latest()->paginate(15);$summaries=$budgets->getCollection()->mapWithKeys(fn($budget)=>[$budget->id=>$tracker->summarize($budget)]);return view('budgets.index',compact('budgets','summaries'));} public function create(){return view('budgets.form',['budget'=>new Budget]);} public function store(BudgetRequest $request){Budget::create($request->validated());return redirect()->route('budgets.index')->with('success','Budget created.');} public function show(Budget $budget,BudgetTracker $tracker){$budget->load(['expenses'=>fn($q)=>$q->latest()]);return view('budgets.show',['budget'=>$budget,'summary'=>$tracker->summarize($budget)]);} public function edit(Budget $budget){return view('budgets.form',compact('budget'));} public function update(BudgetRequest $request,Budget $budget){$budget->update($request->validated());return redirect()->route('budgets.show',$budget)->with('success','Budget updated.');} public function destroy(Budget $budget){$budget->delete();return redirect()->route('budgets.index')->with('success','Budget deleted.');} }
